// Arena-fuzz native L1 for a ported batch (tests/arena_fuzz.h). Generated by tools/asm_port/gen_fuzz_test.py.
#include "test.h"
#include "arena_fuzz.h"
#include "platform/image/original_data.h"
#include "GameZRecoil/zSound/zsnd_grp.h"

#include <cstdio>
#include <cstdlib>
#include <cstring>

namespace {
struct Entry { std::uint32_t va; void* port; int nstack; const char* name; std::vector<std::uint32_t> globals, kept; };
std::vector<Entry> entries()
{
    return {
        {0x004a4590, reinterpret_cast<void*>(&recoil::SoundGroup_ParseNode), 0, "SoundGroup_ParseNode", {0x004e2db8, 0x004e2de4, 0x004e2dec, 0x004e2df8, 0x004e2e20, 0x004e2e54, 0x004e2e64, 0x004e2e9c, 0x004e2eb0, 0x004e2ee0}, {0x004e2ef0, 0x004e2f1c, 0x004e2f24, 0x004e2f54, 0x004e2f60, 0x004e2f90}},
        {0x004a49b0, reinterpret_cast<void*>(&recoil::SoundGroup_ParseVariantNode), 1, "SoundGroup_ParseVariantNode", {0x004e2df8, 0x004e2ef0, 0x004e2f1c, 0x004e2f24, 0x004e2f54, 0x004e2f60, 0x004e2f90}, {}},
        {0x004a50a0, reinterpret_cast<void*>(&recoil::SoundStreamCue_Shutdown), 0, "SoundStreamCue_Shutdown", {0x0056b40c, 0x0056b410, 0x0056b414, 0x0056b420}, {}},
    };
}
}  // namespace

TEST(native_fuzz_auto_sound3_match_original)
{
    if (!rt::map_original()) { CHECK(false); return; }
    af::real_floats() = false;  // ordinary float values in half the scalar words
    int failed = 0;
    const char* only = std::getenv("RECOIL_ONLY");  // diagnostics: run one function by name
    int shard = 0, shards = 1;  // RECOIL_SHARD=i/n: this process runs entries i, i+n, ... (tools/run_tests.py)
    if (const char* s = std::getenv("RECOIL_SHARD")) std::sscanf(s, "%d/%d", &shard, &shards);
    int index = 0;
    for (const Entry& e : entries()) {
        if (index++ % shards != shard) continue;
        if (only && std::strcmp(only, e.name) != 0) continue;
        std::printf("  run  %s\n", e.name); std::fflush(stdout);  // names the function if a crash escapes
        std::vector<af::GlobalRange> gr;
        for (std::uint32_t g : e.globals) gr.push_back({g, recoil::ImageData_Address(g), 4});
        for (std::uint32_t g : e.kept) gr.push_back({g, recoil::ImageData_Address(g), 4, true});  // callee-only: pristine each call
        const af::Result r = af::run(e.va, e.port, e.nstack, 1000, e.va, gr);
        std::printf("  %-40s calls %5d abnormal %5d %s%s\n", e.name, r.calls, r.abnormal, r.bad ? "DIFF " : "ok", r.first.c_str());
        if (r.bad || r.calls - r.abnormal < 50) ++failed;  // at least 50 calls that ended normally (and compared data)
    }
    CHECK_EQ(failed, 0);
}
